head.b:skin:
/* ===== Galeri Drive - Blogger Template ===== */
:root{
  color-scheme:light dark;
  --bg:#E8EBEE; --ink:#18222E; --mute:#5B6773; --line:#C9D0D6;
  --accent:#0E6B68; --accent-hover:#0A5654; --accent-ink:#FFFFFF;
  --link:#0E6B68; --card:#FFFFFF; --ph:#CBD2D8; --err:#9B2C2C;
}
/* Mode gelap otomatis mengikuti pengaturan perangkat */
@media (prefers-color-scheme:dark){
  :root{
    --bg:#10161C; --ink:#E6EBEF; --mute:#93A0AB; --line:#2B3641;
    --accent:#1B7F7B; --accent-hover:#16706C; --accent-ink:#FFFFFF;
    --link:#5CC9C3; --card:#1A232C; --ph:#222C36; --err:#F28B82;
  }
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--ink);font:400 16px/1.6 'Instrument Sans',system-ui,sans-serif}
a{color:var(--link)}
.wrap{max-width:1240px;margin:0 auto;padding:0 20px}

/* Header */
.site-head{padding:56px 0 28px}
.site-head h1{margin:0;font:800 clamp(2.4rem,7vw,5rem)/.95 'Bricolage Grotesque',sans-serif;letter-spacing:-.03em}
.site-head h1 a{color:inherit;text-decoration:none}
.site-head p{margin:14px 0 0;max-width:52ch;color:var(--mute)}

/* Tab album */
.tabs{display:flex;flex-wrap:wrap;gap:6px 22px;border-bottom:1px solid var(--line);margin:8px 0 24px}
.tabs button{background:none;border:0;border-bottom:3px solid transparent;padding:10px 0;margin-bottom:-1px;font:600 1rem 'Instrument Sans',sans-serif;color:var(--mute);cursor:pointer}
.tabs button:hover{color:var(--ink)}
.tabs button[aria-selected=true]{color:var(--ink);border-bottom-color:var(--accent)}
.count{margin:0 0 18px;color:var(--mute);font-size:.9rem}

/* Grid foto */
/* Masonry: lebar kolom sama, tinggi mengikuti rasio asli foto */
.grid{column-width:250px;column-gap:14px}
.card{position:relative;background:var(--ph);overflow:hidden;border-radius:4px;break-inside:avoid;margin:0 0 14px}
.card>button.open{display:block;width:100%;padding:0;border:0;background:none;cursor:zoom-in}
.card img{width:100%;height:auto;display:block;transition:transform .35s ease}
.card:hover img{transform:scale(1.04)}
.card .bar{position:absolute;left:0;right:0;bottom:0;display:flex;align-items:center;justify-content:space-between;gap:8px;padding:28px 10px 10px;background:linear-gradient(transparent,rgba(10,18,26,.72));color:#fff;font-size:.82rem;pointer-events:none}
.card .bar span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.btn-dl{pointer-events:auto;flex:none;display:inline-flex;align-items:center;gap:6px;background:var(--accent);color:var(--accent-ink);text-decoration:none;font:600 .82rem 'Instrument Sans',sans-serif;padding:7px 12px;border-radius:3px}
.btn-dl:hover{background:var(--accent-hover)}
.card .btn-dl{margin-left:auto}
.btn-dl.busy{opacity:.6;pointer-events:none}
.btn-dl svg{width:15px;height:15px}
.status{padding:60px 0;text-align:center;color:var(--mute)}
.status.err{color:var(--err)}

/* Lightbox */
.lb{position:fixed;inset:0;z-index:99;background:rgba(8,14,20,.94);display:none;flex-direction:column}
.lb.on{display:flex}
.lb-top{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 16px;color:#fff}
.lb-top .nm{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.9rem}
.lb-top .act{display:flex;gap:10px;align-items:center}
.lb-x{background:none;border:1px solid rgba(255,255,255,.4);color:#fff;border-radius:3px;padding:7px 12px;font:600 .82rem 'Instrument Sans',sans-serif;cursor:pointer}
.lb-main{touch-action:pan-y pinch-zoom;flex:1;min-height:0;display:flex;align-items:center;justify-content:center;position:relative;padding:0 56px 16px}
.lb-main img{max-width:100%;max-height:100%;object-fit:contain}
.lb-main iframe{display:none;width:100%;height:100%;border:0;background:#000}
.lb.vid .lb-main iframe{display:block}
.lb.vid .lb-main img{display:none}
.play{position:absolute;left:50%;top:50%;width:56px;height:56px;margin:-28px 0 0 -28px;border-radius:50%;background:rgba(10,18,26,.62);border:2px solid rgba(255,255,255,.9);pointer-events:none;display:flex;align-items:center;justify-content:center}
.play svg{width:24px;height:24px;margin-left:3px;fill:#fff}
.dur{position:absolute;top:8px;left:8px;background:rgba(10,18,26,.72);color:#fff;font-size:.75rem;font-weight:600;padding:2px 7px;border-radius:3px;pointer-events:none}
.lb-nav{position:absolute;top:50%;transform:translateY(-50%);width:44px;height:64px;background:rgba(255,255,255,.1);border:0;color:#fff;font-size:1.6rem;cursor:pointer;border-radius:3px}
.lb-nav:hover{background:rgba(255,255,255,.22)}
.lb-prev{left:6px}.lb-next{right:6px}
button:focus-visible,a:focus-visible{outline:3px solid #7FD6D1;outline-offset:2px}

/* Halaman posting biasa */
#main-posts article{background:var(--card);padding:28px;margin:0 0 20px;border-radius:4px}
#main-posts h2{font-family:'Bricolage Grotesque',sans-serif;margin-top:0}
.site-foot{padding:40px 0;color:var(--mute);font-size:.85rem}
@media(max-width:600px){.grid{column-width:auto;column-count:2;column-gap:8px}.card{margin-bottom:8px}.card .bar>span{display:none}.btn-dl{padding:9px}.btn-dl svg{width:18px;height:18px}.btn-dl .t{display:none}.lb-main{padding:0 8px 16px}.lb-nav{width:36px}.lb.vid .lb-nav{display:none}}
@media(prefers-reduced-motion:reduce){.card img{transition:none}html{scroll-behavior:auto}}

body.script:
//
/* =====================================================================
   PENGATURAN - EDIT BAGIAN INI SAJA
   ---------------------------------------------------------------------
   1. Folder Google Drive harus dibagikan: "Siapa saja yang memiliki link".
   2. folderId = bagian akhir URL folder:
      https://drive.google.com/drive/folders/INI_FOLDER_ID
   3. apiKey   = API key Google Cloud (aktifkan "Google Drive API").
      Wajib hanya jika memakai folderId.
   4. Tanpa API key: pakai daftar "files" berisi ID file satu per satu.
      ID file ada di link foto: drive.google.com/file/d/INI_FILE_ID/view
      Untuk video di mode ini tulis: { id: 'FILE_ID', type: 'video' }
   ===================================================================== */
var CONFIG = {
  apiKey: 'AIzaSyD1CjhtmNkqCXXCsylDhQtqiVzkAsvOHvk',
  albums: [
    { title: 'Album Utama', folderId: '1VyN1ZryMDFv7NV1ZmJuFgN-ca8fGAJJA' }
    /* Untuk menambah album lain, tambahkan baris baru:
       { title: 'Album Kedua', folderId: 'ID_FOLDER_LAIN' } */
  ]
};
/* ===================================================================== */

var photos = [], cur = 0;
var $ = function (id) { return document.getElementById(id); };
var thumb = function (id, w) { return 'https://lh3.googleusercontent.com/d/' + id + '=w' + w; };
var dlUrl = function (id) { return 'https://drive.google.com/uc?export=download&id=' + id; };
var isVid = function (p) { return !!(p.video || (p.mimeType && p.mimeType.indexOf('video/') === 0)); };
var fmtDur = function (ms) { var t = Math.round(ms / 1000), h = Math.floor(t / 3600), m = Math.floor(t % 3600 / 60), s = t % 60;
  return (h ? h + ':' + (m < 10 ? '0' : '') : '') + m + ':' + (s < 10 ? '0' : '') + s; };
var PLAY = '<svg viewBox="0 0 24 24"><path d="M6 4l14 8-14 8z"/></svg>';
var esc = function (s) { return String(s).replace(/[&<>"']/g, function (c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); };
var ICON = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v12m0 0l-5-5m5 5l5-5M4 21h16"/></svg>';

async function listFolder(fid) {
  var out = [], tok = '';
  do {
    var q = "'" + fid + "' in parents and (mimeType contains 'image/' or mimeType contains 'video/') and trashed=false";
    var u = 'https://www.googleapis.com/drive/v3/files?q=' + encodeURIComponent(q) +
      '&fields=nextPageToken,files(id,name,mimeType,size,imageMediaMetadata(width,height,rotation),videoMediaMetadata(width,height,durationMillis))&orderBy=name&pageSize=200&key=' + CONFIG.apiKey +
      (tok ? '&pageToken=' + tok : '');
    var r = await fetch(u);
    if (!r.ok) throw new Error('Google Drive API error ' + r.status + '. Periksa API key dan izin folder.');
    var j = await r.json();
    out = out.concat(j.files || []);
    tok = j.nextPageToken || '';
  } while (tok);
  return out;
}

async function loadAlbum(i) {
  var a = CONFIG.albums[i];
  var st = $('status'), grid = $('grid');
  grid.innerHTML = ''; $('count').textContent = '';
  st.className = 'status'; st.textContent = 'Memuat foto...'; st.style.display = '';
  try {
    if (a.files && a.files.length) {
      photos = a.files.map(function (f, n) {
        if (typeof f === 'string') return { id: f, name: 'Foto ' + (n + 1) };
        return { id: f.id, name: f.name || ((f.type === 'video' ? 'Video ' : 'Foto ') + (n + 1)), video: f.type === 'video' };
      });
    } else if (a.folderId) {
      photos = await listFolder(a.folderId);
    } else { photos = []; }
  } catch (e) {
    st.className = 'status err'; st.textContent = e.message; return;
  }
  if (!photos.length) { st.textContent = 'Belum ada foto atau video di album ini.'; return; }
  st.style.display = 'none';
  var nv = photos.filter(isVid).length;
  $('count').textContent = (photos.length - nv) + ' foto' + (nv ? ', ' + nv + ' video' : '');
  var html = '';
  photos.forEach(function (p, n) {
    var nm = esc(p.name.replace(/\.[^.]+$/, ''));
    var v = isVid(p), m = p.imageMediaMetadata || p.videoMediaMetadata, ar = '';
    if (m && m.width && m.height) {
      var odd = (m.rotation === 1 || m.rotation === 3);
      ar = ' style="aspect-ratio:' + (odd ? m.height + '/' + m.width : m.width + '/' + m.height) + '"';
    } else if (v) { ar = ' style="aspect-ratio:16/9"'; }
    var badge = '';
    if (v) {
      var d = p.videoMediaMetadata && p.videoMediaMetadata.durationMillis;
      badge = '<span class="play">' + PLAY + '</span>' + (d ? '<span class="dur">' + fmtDur(+d) + '</span>' : '');
    }
    html += '<figure class="card">' +
      '<button class="open" type="button" data-i="' + n + '" aria-label="' + (v ? 'Putar ' : 'Buka ') + nm + '">' +
      '<img loading="lazy"' + ar + ' alt="' + nm + '" src="' + thumb(p.id, 600) + '" ' +
      'onerror="this.onerror=null;this.src=\'https://drive.google.com/thumbnail?id=' + p.id + '&amp;sz=w600\'"/>' + badge + '</button>' +
      '<div class="bar"><span>' + nm + '</span>' +
      '<a class="btn-dl" data-i="' + n + '" href="' + dlUrl(p.id) + '" target="_blank" rel="noopener" aria-label="Unduh ' + nm + '">' + ICON + '<span class="t">Unduh</span></a></div></figure>';
  });
  grid.innerHTML = html;
}

function renderTabs() {
  var t = $('tabs'), h = '';
  CONFIG.albums.forEach(function (a, i) {
    h += '<button type="button" role="tab" aria-selected="' + (i === 0) + '" data-a="' + i + '">' + esc(a.title) + '</button>';
  });
  t.innerHTML = h;
  if (CONFIG.albums.length < 2) t.style.display = 'none';
  t.addEventListener('click', function (e) {
    var b = e.target.closest('button'); if (!b) return;
    [].forEach.call(t.children, function (x) { x.setAttribute('aria-selected', x === b); });
    loadAlbum(+b.dataset.a);
  });
}

/* Unduh langsung dari website (tanpa membuka Google Drive / pilih akun) */
var BIG = 150 * 1024 * 1024; /* file lebih besar dari ini dialihkan ke unduhan langsung browser */
async function downloadPhoto(p, el) {
  var label = el.querySelector('.t'), old = label ? label.textContent : '';
  var hasKey = CONFIG.apiKey && CONFIG.apiKey.indexOf('ISI_') !== 0;
  var apiUrl = hasKey ? 'https://www.googleapis.com/drive/v3/files/' + p.id + '?alt=media&key=' + CONFIG.apiKey : '';
  if (apiUrl && p.size && +p.size > BIG) { window.open(apiUrl, '_blank'); return; }
  el.classList.add('busy');
  if (label) label.textContent = 'Mengunduh...';
  try {
    var urls = [];
    if (apiUrl) urls.push(apiUrl);
    if (!isVid(p)) urls.push('https://lh3.googleusercontent.com/d/' + p.id + '=s0');
    var blob = null;
    for (var k = 0; k < urls.length && !blob; k++) {
      try {
        var r = await fetch(urls[k]);
        if (!r.ok) continue;
        var total = +p.size || +r.headers.get('content-length') || 0;
        if (r.body && r.body.getReader && total) {
          var rd = r.body.getReader(), parts = [], got = 0;
          for (;;) {
            var c = await rd.read();
            if (c.done) break;
            parts.push(c.value); got += c.value.length;
            if (label) label.textContent = Math.min(99, Math.round(got / total * 100)) + '%';
          }
          blob = new Blob(parts, { type: r.headers.get('content-type') || '' });
        } else { blob = await r.blob(); }
      } catch (err) { /* coba sumber berikutnya */ }
    }
    if (!blob) throw new Error('gagal');
    var name = p.name;
    if (!/\.[A-Za-z0-9]{2,5}$/.test(name)) {
      var ext = (blob.type.split('/')[1] || (isVid(p) ? 'mp4' : 'jpg')).replace('jpeg', 'jpg');
      name += '.' + ext;
    }
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = name;
    document.body.appendChild(a);
    a.click();
    setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 4000);
  } catch (e) {
    window.open(dlUrl(p.id), '_blank'); /* cadangan: unduh lewat Google Drive */
  } finally {
    el.classList.remove('busy');
    if (label) label.textContent = old;
  }
}

/* Lightbox */
function show(i) {
  cur = (i + photos.length) % photos.length;
  var p = photos[cur];
  var v = isVid(p);
  $('lb').classList.toggle('vid', v);
  $('lb-vid').src = v ? 'https://drive.google.com/file/d/' + p.id + '/preview' : '';
  $('lb-img').src = v ? '' : thumb(p.id, 1800);
  $('lb-img').alt = p.name;
  $('lb-nm').textContent = p.name + '  (' + (cur + 1) + '/' + photos.length + ')';
  $('lb-dl').href = dlUrl(p.id);
  $('lb').classList.add('on');
  document.body.style.overflow = 'hidden';
}
function closeLb() { $('lb').classList.remove('on', 'vid'); $('lb-img').src = ''; $('lb-vid').src = ''; document.body.style.overflow = ''; }

$('grid').addEventListener('click', function (e) {
  var d = e.target.closest('a.btn-dl');
  if (d) { e.preventDefault(); downloadPhoto(photos[+d.dataset.i], d); return; }
  var b = e.target.closest('button.open');
  if (b) show(+b.dataset.i);
});
$('lb-dl').addEventListener('click', function (e) {
  e.preventDefault(); downloadPhoto(photos[cur], this);
});
$('lb-x').onclick = closeLb;
$('lb-prev').onclick = function () { show(cur - 1); };
$('lb-next').onclick = function () { show(cur + 1); };
$('lb').addEventListener('click', function (e) { if (e.target.classList.contains('lb-main')) closeLb(); });

/* Geser kiri/kanan di tampilan besar */
(function () {
  var box = document.querySelector('.lb-main'), img = $('lb-img');
  var sx = 0, sy = 0, on = false;
  box.addEventListener('touchstart', function (e) {
    if (e.touches.length !== 1) { on = false; return; }
    sx = e.touches[0].clientX; sy = e.touches[0].clientY; on = true;
    img.style.transition = 'none';
  }, { passive: true });
  box.addEventListener('touchmove', function (e) {
    if (!on) return;
    var dx = e.touches[0].clientX - sx, dy = e.touches[0].clientY - sy;
    if (Math.abs(dx) > Math.abs(dy)) img.style.transform = 'translateX(' + dx + 'px)';
  }, { passive: true });
  box.addEventListener('touchend', function (e) {
    if (!on) return;
    on = false;
    var dx = e.changedTouches[0].clientX - sx, dy = e.changedTouches[0].clientY - sy;
    img.style.transition = 'transform .2s ease';
    img.style.transform = '';
    if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.5) show(cur + (dx < 0 ? 1 : -1));
  }, { passive: true });
  box.addEventListener('touchcancel', function () { on = false; img.style.transform = ''; }, { passive: true });
})();
document.addEventListener('keydown', function (e) {
  if (!$('lb').classList.contains('on')) return;
  if (e.key === 'Escape') closeLb();
  if (e.key === 'ArrowLeft') show(cur - 1);
  if (e.key === 'ArrowRight') show(cur + 1);
});

$('lb-dl').innerHTML = ICON + '<span class="t">Unduh</span>';
renderTabs();
loadAlbum(0);
//
